import json, sys

args = json.loads(sys.stdin.read())
task = args["task"]
planted = {}

def write_csv(name, header, rows):
    with open(name, "w") as f:
        f.write(",".join(header) + "\n")
        for r in rows:
            f.write(",".join(str(x) for x in r) + "\n")

def dens(x):
    return round(float(x), 1)

if task == "single_control":
    rows = []
    for i, s in enumerate(args["samples"], start=1):
        rows.append([i, s["name"], args["target"], dens(args["k_target"] * s["level"] * s["loading"])])
        rows.append([i, s["name"], args["control"], dens(args["k_control"] * s["loading"])])
    write_csv(args["file"], ["lane", "sample", "protein", "density"], rows)
    lv = {s["name"]: float(s["level"]) for s in args["samples"]}
    planted["fold_d_vs_a"] = lv["D"] / lv["A"]
    planted["highest_sample"] = max(lv, key=lambda k: lv[k])

elif task == "two_step":
    rows = []
    for i, s in enumerate(args["samples"], start=1):
        L = float(s["loading"])
        rows.append([i, s["name"], "PSMAD2", dens(args["k_phospho"] * s["phospho"] * L)])
        rows.append([i, s["name"], "SMAD2", dens(args["k_total"] * s["total"] * L)])
        rows.append([i, s["name"], "GAPDH", dens(args["k_control"] * L)])
    write_csv(args["file"], ["lane", "sample", "protein", "density"], rows)
    c, t = args["samples"][0], args["samples"][1]
    planted["psmad2_fold_change"] = (float(t["phospho"]) / float(t["total"])) / (float(c["phospho"]) / float(c["total"]))
    planted["smad2_fold_change"] = float(t["total"]) / float(c["total"])

elif task == "modform":
    rows = []
    for i, s in enumerate(args["samples"], start=1):
        L = float(s["loading"])
        rows.append([i, s["name"], args["phospho_name"], dens(args["k_phospho"] * s["phospho"] * L)])
        rows.append([i, s["name"], args["total_name"], dens(args["k_total"] * s["total"] * L)])
        rows.append([i, s["name"], args["ref_name"], dens(args["k_ref"] * L)])
    write_csv(args["file"], ["lane", "sample", "protein", "density"], rows)
    tot = {s["name"]: float(s["total"]) for s in args["samples"]}
    frac = {s["name"]: float(s["phospho"]) / float(s["total"]) for s in args["samples"]}
    base = args["baseline"]
    for field, sample in args.get("folds", {}).items():
        planted[field] = tot[sample] / tot[base]
    for field, sample in args.get("fraction_folds", {}).items():
        planted[field] = frac[sample] / frac[base]
    planted["highest_phospho_fraction_sample"] = max(frac, key=lambda k: frac[k])

print(json.dumps(planted))

