import csv, json, os

def table(path):
    t = {}
    with open(path) as f:
        for r in csv.DictReader(f):
            t.setdefault(r["sample"].strip(), {})[r["protein"].strip()] = float(r["density"])
    return t

res = {}
for fn in sorted(os.listdir("/task")):
    if not fn.lower().endswith(".csv"):
        continue
    t = table(os.path.join("/task", fn))
    if fn == "blot_densitometry.csv":
        norm = {s: v["TNC"] / v["GAPDH"] for s, v in t.items()}
        res["fold_d_vs_a"] = norm["D"] / norm["A"]
        res["highest_sample"] = max(norm, key=lambda k: norm[k])
    elif fn == "psmad2_blot_exp2.csv":
        n = {s: {p: v[p] / v["GAPDH"] for p in ("PSMAD2", "SMAD2")} for s, v in t.items()}
        res["psmad2_fold_change"] = (n["P144"]["PSMAD2"] / n["P144"]["SMAD2"]) / (n["control"]["PSMAD2"] / n["control"]["SMAD2"])
        res["smad2_fold_change"] = n["P144"]["SMAD2"] / n["control"]["SMAD2"]
    elif fn == "psmad2_blot_multi.csv":
        n = {s: {p: v[p] / v["GAPDH"] for p in ("PSMAD2", "SMAD2")} for s, v in t.items()}
        res["smad2_fold_drugx"] = n["drugX"]["SMAD2"] / n["control"]["SMAD2"]
        res["smad2_fold_drugy"] = n["drugY"]["SMAD2"] / n["control"]["SMAD2"]
        frac = {s: n[s]["PSMAD2"] / n[s]["SMAD2"] for s in n}
        res["highest_phospho_fraction_sample"] = max(frac, key=lambda k: frac[k])
    elif fn == "erk_blot_stainfree.csv":
        n = {s: {p: v[p] / v["TotalProteinStain"] for p in ("PERK", "ERK")} for s, v in t.items()}
        res["erk_fold_cmpdb"] = n["cmpdB"]["ERK"] / n["untreated"]["ERK"]
        frac = {s: n[s]["PERK"] / n[s]["ERK"] for s in n}
        res["perk_fraction_fold_cmpda"] = frac["cmpdA"] / frac["untreated"]
        res["highest_phospho_fraction_sample"] = max(frac, key=lambda k: frac[k])

with open("/work/results.json", "w") as f:
    json.dump(res, f)
